module adder_4bit_sva (
    input logic       clk,
    input logic [3:0] A,
    input logic [3:0] B,
    input logic [3:0] S,
    input logic       C_out
);

    // Combined outputs must equal the 5-bit sum of A and B.
    check_total_addition: assert property (
        @(posedge clk)
        {C_out, S} == ({1'b0, A} + {1'b0, B})
    );

    // Bit 0 sum is the XOR of the least-significant input bits.
    check_bit0_sum: assert property (
        @(posedge clk)
        S[0] == (A[0] ^ B[0])
    );

    // Bit 1 sum includes the carry generated by bit 0.
    check_bit1_ripple_sum: assert property (
        @(posedge clk)
        S[1] == (A[1] ^ B[1] ^ (A[0] & B[0]))
    );

    // Bit 2 sum includes the ripple carry from bits 0 and 1.
    check_bit2_ripple_sum: assert property (
        @(posedge clk)
        S[2] == (A[2] ^ B[2] ^ ((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))))
    );

    // Bit 3 sum includes the ripple carry from bits 0 through 2.
    check_bit3_ripple_sum: assert property (
        @(posedge clk)
        S[3] == (A[3] ^ B[3] ^ ((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2]))))
    );

    // Final carry-out follows the full-adder carry equation at bit 3.
    check_final_carry: assert property (
        @(posedge clk)
        C_out == ((A[3] & B[3]) | (((A[2] & B[2]) | (((A[1] & B[1]) | ((A[0] & B[0]) & (A[1] ^ B[1]))) & (A[2] ^ B[2]))) & (A[3] ^ B[3])))
    );

    // Adding zero on A leaves B unchanged and produces no carry.
    check_add_zero_from_a: assert property (
        @(posedge clk)
        (A == 4'b0000) |-> ((S == B) && (C_out == 1'b0))
    );

    // Adding zero on B leaves A unchanged and produces no carry.
    check_add_zero_from_b: assert property (
        @(posedge clk)
        (B == 4'b0000) |-> ((S == A) && (C_out == 1'b0))
    );

endmodule